script:
(function () {
  'use strict';
  // Withdrawals from a tax-deferred plan (traditional 401(k), 403(b), 457 or IRA), year by year from 2026.
  //   start balance B = prior December 31 balance
  //   RMD             = B / Uniform Lifetime Table period for the age reached that year (from the RMD
  //                     start age; 0 before it)
  //   withdrawal W    = larger of the planned amount (rising by the yearly increase) and the RMD,
  //                     capped at what the account holds: end balance = B x (1 + return) - W
  //   federal tax     = tax(other income + W) - tax(other income), 2026 brackets and deductions with
  //                     dollar thresholds indexed each year by the yearly increase
  //   state tax       = flat rate x W;  10% penalty on W in years you are under 59 1/2 all year
  //                     (year-end age 59 or less)
  // Checked in Node (scratch tests, hand calculations): MFJ, both 65+ in 2026, $30,000 other income,
  //   $40,000 withdrawal -> deduction $32,200 + 2 x $1,650 + 2 x $6,000 = $47,500, taxable $22,500,
  //   federal tax $2,250 (all 10%); single under 65, $50,000 other + $10,000 -> $1,200 (12% band);
  //   RMD for a 75-year-old on $500,000 = $500,000 / 24.6 = $20,325.20; born 1951 -> first RMD 2024
  //   at 73, born 1960 -> 2035 at 75; the year-end balance recursion matches rmd-calculator.
  //
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Brackets and standard deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21).
  // Additional standard deduction (65+) and the senior deduction ($6,000 per person 65+, tax years
  //   2025-2028 only, reduced by 6% of income above $75,000 / $150,000 joint): IRC 63(f) and
  //   151(d)(5)(C) as amended by P.L. 119-21. Same constants as take-home-paycheck-calculator.
  // 10% additional tax on early distributions before age 59 1/2: IRC 72(t).
  // Uniform Lifetime Table: IRS Publication 590-B, Appendix B, Table III (distribution years 2022
  //   and later). RMD start age (SECURE 2.0 Act): born 1950 or earlier 72, 1951-1959 73, 1960+ 75.
  //   Same table as rmd-calculator.
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, hoh: 24150 };
  var ADDITIONAL_65 = { single: 2050, hoh: 2050, mfj: 1650 }; // per person 65+
  var SENIOR_DEDUCTION = 6000, SENIOR_PHASEOUT_RATE = 0.06, SENIOR_LAST_YEAR = 2028;
  var SENIOR_PHASEOUT_START = { single: 75000, hoh: 75000, mfj: 150000 };
  var EARLY_PENALTY = 0.10;
  var UNIFORM_TABLE = {
    72: 27.4, 73: 26.5, 74: 25.5, 75: 24.6, 76: 23.7, 77: 22.9, 78: 22.0, 79: 21.1, 80: 20.2,
    81: 19.4, 82: 18.5, 83: 17.7, 84: 16.8, 85: 16.0, 86: 15.2, 87: 14.4, 88: 13.7, 89: 12.9,
    90: 12.2, 91: 11.5, 92: 10.8, 93: 10.1, 94: 9.5, 95: 8.9, 96: 8.4, 97: 7.8, 98: 7.3,
    99: 6.8, 100: 6.4, 101: 6.0, 102: 5.6, 103: 5.2, 104: 4.9, 105: 4.6, 106: 4.3, 107: 4.1,
    108: 3.9, 109: 3.7, 110: 3.5, 111: 3.4, 112: 3.3, 113: 3.1, 114: 3.0, 115: 2.9, 116: 2.8,
    117: 2.7, 118: 2.5, 119: 2.3, 120: 2.0
  };
  // ---------------------------------------------------------------------------------------

  function rmdStartAge(birthYear) { return birthYear <= 1950 ? 72 : birthYear <= 1959 ? 73 : 75; }
  function divisor(age) { return age >= 120 ? UNIFORM_TABLE[120] : UNIFORM_TABLE[age] || null; }

  function bracketTax(taxable, limits, scale) {
    var tax = 0, lower = 0, marginal = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] * scale : Infinity;
      if (taxable > lower) { tax += (Math.min(taxable, upper) - lower) * RATES[i]; marginal = RATES[i]; }
      lower = upper;
    }
    return { tax: tax, marginal: marginal };
  }

  // Federal tax on ordinary income for one year; scale indexes the dollar thresholds.
  function federal(income, status, seniors, year, scale) {
    var deduction = (STANDARD_DEDUCTION[status] + seniors * ADDITIONAL_65[status]) * scale;
    if (seniors > 0 && year <= SENIOR_LAST_YEAR) {
      deduction += seniors * Math.max(0, SENIOR_DEDUCTION - SENIOR_PHASEOUT_RATE * Math.max(0, income - SENIOR_PHASEOUT_START[status]));
    }
    return bracketTax(Math.max(0, income - deduction), BRACKETS[status], scale);
  }

  // p: birth, spouseBirth, balance, withdraw, increase, status, other, ret, state (decimals), toAge
  function project(p) {
    var rows = [], b = p.balance, totalW = 0, totalTax = 0, emptyAge = null;
    for (var year = TAX_YEAR; year - p.birth <= p.toAge; year++) {
      var age = year - p.birth, t = year - TAX_YEAR, scale = Math.pow(1 + p.increase, t);
      var seniors = (age >= 65 ? 1 : 0) + (p.status === 'mfj' && year - p.spouseBirth >= 65 ? 1 : 0);
      var other = p.other * scale, planned = p.withdraw * scale;
      var d = age >= rmdStartAge(p.birth) ? divisor(age) : null;
      var rmd = d ? b / d : 0;
      var available = Math.max(0, b * (1 + p.ret));
      var w = Math.min(Math.max(planned, rmd), available);
      var base = federal(other, p.status, seniors, year, scale), withW = federal(other + w, p.status, seniors, year, scale);
      var fed = withW.tax - base.tax, st = w * p.state, pen = age <= 59 ? w * EARLY_PENALTY : 0;
      var end = available - w;
      rows.push({ year: year, age: age, start: b, rmd: Math.min(rmd, available), w: w, fed: fed, st: st, pen: pen,
                  net: w - fed - st - pen, end: end, marginal: withW.marginal, planned: planned });
      totalW += w; totalTax += fed + st + pen;
      b = end;
      if (b < 0.005 && w > 0) { emptyAge = age; break; }
    }
    return { rows: rows, totalW: totalW, totalTax: totalTax, emptyAge: emptyAge,
             firstRmdYear: p.birth + rmdStartAge(p.birth), startAge: rmdStartAge(p.birth) };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return isFinite(x) ? moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x) : '–'; } };

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function update() {
    var birth = Math.round(num('pwBirth')), spouseBirth = Math.round(num('pwSpouseBirth')), balance = num('pwBalance'),
        withdraw = num('pwWithdraw'), increase = num('pwIncrease'), other = num('pwOther'), ret = num('pwReturn'),
        state = num('pwState'), toAge = Math.round(num('pwToAge')), status = document.getElementById('pwStatus').value;
    var spouseWrap = document.getElementById('pwSpouseWrap');
    if (spouseWrap) spouseWrap.hidden = status !== 'mfj';
    var error = document.getElementById('pwError');
    var age2026 = TAX_YEAR - birth;
    var bad = [birth, spouseBirth, balance, withdraw, increase, other, ret, state, toAge].some(isNaN) || !BRACKETS[status] ||
              birth < 1930 || birth > 2005 || spouseBirth < 1930 || spouseBirth > 2005 || balance < 0 || withdraw < 0 ||
              increase < 0 || increase > 10 || other < 0 || ret < -20 || ret > 20 || state < 0 || state > 15 ||
              toAge < 60 || toAge > 110 || toAge < age2026;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Use birth years from 1930 to 2005, non-negative amounts, a yearly increase up to 10%, a return from ' +
                          '-20% to 20%, a state rate up to 15% and a projection age from 60 to 110 (not below your age in ' + TAX_YEAR + ').';
      return;
    }
    var r = project({ birth: birth, spouseBirth: spouseBirth, balance: balance, withdraw: withdraw, increase: increase / 100,
                      status: status, other: other, ret: ret / 100, state: state / 100, toAge: toAge });
    var f = r.rows[0];
    set('pwNet', money.format(f.net));
    set('pwTax', money.format(f.fed + f.st + f.pen));
    if (r.firstRmdYear < TAX_YEAR) { set('pwRmdStartLabel', 'RMDs'); set('pwRmdStart', 'Already required'); }
    else {
      set('pwRmdStartLabel', 'First RMD (age ' + r.startAge + ')');
      var rmdRow = r.rows.filter(function (x) { return x.year === r.firstRmdYear; })[0];
      set('pwRmdStart', rmdRow ? r.firstRmdYear + ': ' + money.format(rmdRow.rmd) : String(r.firstRmdYear));
    }
    set('pwAge', String(age2026));
    set('pwGross', money.format(f.w));
    set('pwRmd', f.age >= r.startAge ? money.format(f.rmd) : 'None yet');
    set('pwFed', money.format(f.fed));
    set('pwSt', money.format(f.st));
    set('pwPen', f.pen > 0 ? money.format(f.pen) : 'None (59½ or older)');
    set('pwBracket', Math.round(f.marginal * 100) + '%');
    var last = r.rows[r.rows.length - 1];
    set('pwTotalsLabel', 'Total withdrawn / total tax to age ' + last.age);
    set('pwTotals', money.format(r.totalW) + ' / ' + money.format(r.totalTax));
    var forced = r.rows.filter(function (x) { return x.rmd > x.planned + 0.5; });
    var summary = balance === 0 ? 'Enter your plan balance to project withdrawals, RMDs and tax.' : r.emptyAge !== null
      ? 'At these withdrawals the plan runs out at about age ' + r.emptyAge + '.'
      : 'The plan still holds ' + money.format(last.end) + ' at age ' + last.age + '.';
    if (forced.length) summary += ' RMDs force a larger withdrawal than you planned from ' + forced[0].year +
      ' (age ' + forced[0].age + '), raising your taxable income in those years.';
    else if (r.firstRmdYear <= last.year) summary += ' Your planned withdrawals stay above the RMD every year shown.';
    if (f.pen > 0) summary += ' Withdrawals before age 59½ add a 10% penalty unless an exception applies.';
    set('pwSummary', summary);

    var body = document.getElementById('pwSchedule');
    body.textContent = '';
    r.rows.forEach(function (x) {
      var tr = document.createElement('tr');
      [x.year, x.age, money.format(x.start), x.rmd > 0 ? money.format(x.rmd) : '–', money.format(x.w), money.format(x.fed),
       money.format(x.st + x.pen), money.format(x.net), money.format(x.end)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('pwForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
